<?php

namespace Tests\Feature\Ai;

use Illuminate\Support\Facades\Artisan;
use Illuminate\Support\Facades\File;
use Illuminate\Support\Facades\Schema;
use PHPUnit\Framework\Attributes\DataProvider;
use Tests\TestCase;

class AtlasAiSelfConstructionCommandTest extends TestCase
{
    protected function setUp(): void
    {
        parent::setUp();

        File::deleteDirectory(storage_path('app/atlas/self-construction/reservations'));
    }

    protected function tearDown(): void
    {
        File::deleteDirectory(storage_path('app/atlas/self-construction/reservations'));

        parent::tearDown();
    }

    private function completeSelfConstructionSplitPackets(
        string $actorPrefix = 'codex-',
        string $sessionPrefix = 'session-',
        string $evidencePrefix = '',
    ): void
    {
        $packets = [
            'AIP-SPLIT-SELF-CONSTRUCTION-DOCS-0001',
            'AIP-SPLIT-SELF-CONSTRUCTION-PACKET-CONTRACTS-0002',
            'AIP-SPLIT-SELF-CONSTRUCTION-COMMAND-0003',
            'AIP-SPLIT-SELF-CONSTRUCTION-SERVICE-0004',
            'AIP-SPLIT-SELF-CONSTRUCTION-EVIDENCE-0005',
        ];

        foreach ($packets as $index => $packetId) {
            $actor = $actorPrefix.($index + 1);
            $session = $sessionPrefix.($index + 1);

            Artisan::call('atlas:ai:self-construction', [
                '--claim-packet' => true,
                '--packet' => $packetId,
                '--actor' => $actor,
                '--session' => $session,
                '--json' => true,
            ]);

            Artisan::call('atlas:ai:self-construction', [
                '--complete-packet' => true,
                '--packet' => $packetId,
                '--actor' => $actor,
                '--session' => $session,
                '--reason' => 'packet_scope_finished',
                '--evidence-hash' => hash('sha256', $evidencePrefix.$packetId),
                '--json' => true,
            ]);
        }
    }

    private function selfConstructionJson(array $arguments): array
    {
        $exit = Artisan::call('atlas:ai:self-construction', $arguments);
        $payload = json_decode(Artisan::output(), true, flags: JSON_THROW_ON_ERROR);

        $this->assertSame(0, $exit);

        return $payload;
    }

    #[DataProvider('humanOutputCommandProvider')]
    public function test_command_human_output_lists_section(string $option, array $expectedStrings): void
    {
        $exit = Artisan::call('atlas:ai:self-construction', [
            $option => true,
        ]);
        $output = Artisan::output();

        $this->assertSame(0, $exit);

        foreach ($expectedStrings as $expectedString) {
            $this->assertStringContainsString($expectedString, $output);
        }
    }

