    private function completeSelfConstructionSplitPacketsWithActors(array $actors, string $sessionPrefix = 'session-'): void
    {
        $packets = [
            'AIP-SPLIT-SELF-CONSTRUCTION-DOCS-0001',
            'AIP-SPLIT-SELF-CONSTRUCTION-PACKET-CONTRACTS-0002',
            'AIP-SPLIT-SELF-CONSTRUCTION-COMMAND-0003',
            'AIP-SPLIT-SELF-CONSTRUCTION-SERVICE-0004',
            'AIP-SPLIT-SELF-CONSTRUCTION-EVIDENCE-0005',
        ];

        foreach ($packets as $index => $packetId) {
            $actor = $actors[$index];
            $session = $sessionPrefix.($index + 1);

            Artisan::call('atlas:ai:self-construction', [
                '--claim-packet' => true,
                '--packet' => $packetId,
                '--actor' => $actor,
                '--session' => $session,
                '--json' => true,
            ]);

            Artisan::call('atlas:ai:self-construction', [
                '--complete-packet' => true,
                '--packet' => $packetId,
                '--actor' => $actor,
                '--session' => $session,
                '--reason' => 'packet_scope_finished',
                '--evidence-hash' => hash('sha256', $packetId),
                '--json' => true,
            ]);
        }
    }

    #[DataProvider('jsonContractCommandProvider')]
    public function test_command_returns_json_contract(array $arguments, array $checks, array $setup = []): void
    {
        foreach ($setup as [$method, $args]) {
            $this->{$method}(...$args);
        }

        $payload = $this->selfConstructionJson($arguments);

        foreach ($checks as $check) {
            [$kind, $path] = $check;
            $expected = $check[2] ?? null;

            match ($kind) {
                'same' => $this->assertSame($expected, data_get($payload, $path)),
                'true' => $this->assertTrue(data_get($payload, $path)),
                'false' => $this->assertFalse(data_get($payload, $path)),
                'null' => $this->assertNull(data_get($payload, $path)),
                'is_int' => $this->assertIsInt(data_get($payload, $path)),
                'is_bool' => $this->assertIsBool(data_get($payload, $path)),
                'is_array' => $this->assertIsArray(data_get($payload, $path)),
                'contains' => $this->assertContains($expected, data_get($payload, $path)),
                'not_contains' => $this->assertNotContains($expected, data_get($payload, $path)),
                'in' => $this->assertContains(data_get($payload, $path), $expected),
                'regex' => $this->assertMatchesRegularExpression($expected, data_get($payload, $path)),
                'gt' => $this->assertGreaterThan($expected, data_get($payload, $path)),
                'gte' => $this->assertGreaterThanOrEqual($expected, data_get($payload, $path)),
                'has_key' => $this->assertArrayHasKey($expected, data_get($payload, $path)),
                'string_contains' => $this->assertStringContainsString($expected, data_get($payload, $path)),
                default => $this->fail('Unknown check kind: '.$kind),
            };
        }
    }

